import React from "react";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import QMoiKernelPanel from "./QMoiKernelPanel";
import { server } from "../../mocks/server";

// MSW setup is handled in src/setupTests.ts

describe("QMoiKernelPanel Integration", () => {
  let localServer: any;

  beforeAll(async () => {
    // Create a local MSW server for this test file so it doesn't depend on
    // global setup ordering. Prefer ESM dynamic import of 'msw/node'; if
    // unavailable, fall back to using the shared `server` export.
    try {
      const msw = await import("msw");
      const mswnode = await import("msw/node");
      const helpers = (msw as any).rest ?? (msw as any).http;
      if (!helpers) throw new Error("msw helpers not found");

      const handlers = [
        helpers.get("/api/qmoi/status", (req: any, res: any, ctx: any) =>
          res(
            ctx.status(200),
            ctx.json({
              status: "OK",
              last_check: "2024-06-01T12:00:00Z",
              mutation_count: 5,
              logs: ["Log 1", "Log 2"],
            })
          )
        ),
        helpers.post("/api/qmoi/payload", (req: any, res: any, ctx: any) => {
          const action = req.url.searchParams.get("qfix")
            ? "QFix"
            : req.url.searchParams.get("qoptimize")
            ? "QOptimize"
            : req.url.searchParams.get("qsecure")
            ? "QSecure"
            : "Unknown";
          return res(ctx.status(200), ctx.json({ message: `${action} done` }));
        }),
      ];

      localServer = mswnode.setupServer(...handlers);
      localServer.listen({
        onUnhandledRequest: (req: any) =>
          console.error("TEST MSW UNHANDLED:", req.method, String(req.url)),
      });
    } catch (e) {
      // Fallback: try to use shared server and helpers, or mock fetch as last resort
      // eslint-disable-next-line no-console
      console.warn("TEST: msw/node unavailable, falling back to shared server", e);
      try {
        server.listen();
      } catch (er) {
        // ignore
      }
      const msw = await import("msw");
      const helpers = (msw as any).rest ?? (msw as any).http;
      if (helpers) {
        server.use(
          helpers.get("/api/qmoi/status", (req: any, res: any, ctx: any) =>
            res(
              ctx.status(200),
              ctx.json({
                status: "OK",
                last_check: "2024-06-01T12:00:00Z",
                mutation_count: 5,
                logs: ["Log 1", "Log 2"],
              })
            )
          ),
          helpers.post("/api/qmoi/payload", (req: any, res: any, ctx: any) =>
            res(ctx.status(200), ctx.json({ message: "QFix done" }))
          )
        );
      } else {
        jest
          .spyOn(global, "fetch" as any)
          .mockImplementation(async (input: any) => {
            const url = typeof input === "string" ? input : input.url;
            if (url.endsWith("/api/qmoi/status")) {
              return new Response(
                JSON.stringify({
                  status: "OK",
                  last_check: "2024-06-01T12:00:00Z",
                  mutation_count: 5,
                  logs: ["Log 1", "Log 2"],
                }),
                { status: 200 }
              );
            }
            if (url.includes("/api/qmoi/payload")) {
              return new Response(JSON.stringify({ message: "QFix done" }), {
                status: 200,
              });
            }
            return Promise.reject(new Error("Unexpected fetch in test"));
          });
      }
    }
    // cleanup local server after tests
    afterAll(() => {
      try {
        if (localServer && typeof localServer.close === "function") localServer.close();
      } catch (er) {
        // ignore
      }
      try {
        server.close();
      } catch (er) {
        // ignore
      }
    });
  });
  it("fetches and displays status from API", async () => {
    // Default MSW handlers (registered in test setup) provide the mocked status
    render(<QMoiKernelPanel isMaster={true} />);
    expect(await screen.findByText("OK")).toBeInTheDocument();
    expect(screen.getByText("Log 1")).toBeInTheDocument();
    expect(screen.getByText("Log 2")).toBeInTheDocument();
  });

  it("runs QFix and updates last action", async () => {
    // Default MSW handlers handle POST /api/qmoi/payload and status GET
    render(<QMoiKernelPanel isMaster={true} />);
    // wait for initial status fetch to complete and UI to update
    await screen.findByText("OK");
    fireEvent.click(screen.getByRole("button", { name: /Run QFix/i }));
    await waitFor(() =>
      expect(screen.getByText(/Last Action:/)).toBeInTheDocument()
    );
    expect(screen.getByText("QFix done")).toBeInTheDocument();
  });

  it("handles API error gracefully", async () => {
    // Override status handler to simulate an error response
    const msw = await import("msw");
    server.use(
      (msw as any).http.get(
        "/api/qmoi/status",
        (req: any, res: any, ctx: any) => {
          return res(ctx.status(500));
        }
      )
    );
    render(<QMoiKernelPanel isMaster={true} />);
    await waitFor(() => expect(screen.getByText(/Error:/)).toBeInTheDocument());
  });
});
